-- VEGA expanded feature modules (initial data model)
create table if not exists public.portal_users(id uuid primary key default gen_random_uuid(), company_id uuid references public.companies(id), exhibitor_id uuid references public.exhibitors(id), user_id uuid references auth.users(id), portal_role text default 'exhibitor', active boolean default true, created_at timestamptz default now());
create table if not exists public.visitors(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), full_name text not null, email text, phone text, ticket_type text default 'general', ticket_code text unique, registered_at timestamptz default now(), checked_in_at timestamptz);
create table if not exists public.event_pages(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), title text not null, slug text unique, domain text, content jsonb default '{}', publish_status text default 'draft', created_at timestamptz default now());
create table if not exists public.sponsor_packages(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), package_name text not null, price numeric(12,2) default 0, currency char(3) default 'AED', deliverables jsonb default '[]', active boolean default true);
create table if not exists public.online_payments(id uuid primary key default gen_random_uuid(), invoice_id uuid references public.invoices(id), company_id uuid references public.companies(id), gateway text, payment_reference text, amount numeric(12,2) not null, currency char(3) default 'AED', status text default 'pending', paid_at timestamptz, created_at timestamptz default now());
create table if not exists public.badges(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), visitor_id uuid references public.visitors(id), exhibitor_id uuid references public.exhibitors(id), badge_code text unique, badge_type text, access_zones jsonb default '[]', printed_at timestamptz, checked_in_at timestamptz);
create table if not exists public.venues(id uuid primary key default gen_random_uuid(), name text not null, address text, halls jsonb default '[]', floorplan_path text, created_at timestamptz default now());
create table if not exists public.shipments(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), company_id uuid references public.companies(id), carrier text, tracking_number text, delivery_slot timestamptz, customs_docs jsonb default '[]', status text default 'registered', created_at timestamptz default now());
create table if not exists public.facility_bookings(id uuid primary key default gen_random_uuid(), venue_id uuid references public.venues(id), exhibition_id uuid references public.exhibitions(id), facility_name text not null, booking_date date, service_type text, assigned_team text, status text default 'requested');
create table if not exists public.vendor_rfqs(id uuid primary key default gen_random_uuid(), supplier_id uuid references public.suppliers(id), exhibition_id uuid references public.exhibitions(id), rfq_number text unique, description text, due_date date, status text default 'open', created_at timestamptz default now());
create table if not exists public.support_tickets(id uuid primary key default gen_random_uuid(), company_id uuid references public.companies(id), exhibitor_id uuid references public.exhibitors(id), requester text, category text, subject text not null, description text, priority text default 'normal', assigned_to uuid references auth.users(id), sla_due timestamptz, status text default 'open', created_at timestamptz default now());
create table if not exists public.project_dependencies(id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id), task_id uuid, depends_on_task_id uuid, dependency_type text default 'finish_to_start');
create table if not exists public.risk_register(id uuid primary key default gen_random_uuid(), exhibition_id uuid references public.exhibitions(id), title text not null, category text, owner_id uuid references auth.users(id), due_date date, severity text default 'medium', mitigation text, status text default 'open');
create table if not exists public.analytics_saved_reports(id uuid primary key default gen_random_uuid(), name text not null, report_config jsonb default '{}', created_by uuid references auth.users(id), created_at timestamptz default now());
create table if not exists public.mobile_sync_queue(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), entity_type text not null, payload jsonb not null, sync_status text default 'queued', created_at timestamptz default now());
